-- C/C++: parsers + filetypes.
-- clangd covers both C and C++ (and Objective-C), so one LSP entry serves both.
-- LSP (clangd) and keymaps live here.
return {
  parsers = { "c", "cpp" },
  filetypes = { "c", "cpp" },
  -- clangd: the LLVM C/C++ language server. Prefers a compile_commands.json
  -- (generated by CMake/Make/etc.); without one it falls back to loose flags
  -- and still delivers diagnostics/hover, just without cross-file accuracy.
  lsp = {
    name = "clangd",
    cmd = { "clangd" },
    filetypes = { "c", "cpp" },
    root_markers = {
      "compile_commands.json",
      ".clangd",
      "CMakeLists.txt",
      "Makefile",
      ".git",
    },
  },
}